style.css:
h1 {
  display: none;


} 
/* START button */
button[onclick*="start"] {
  margin-left: 16px;
  margin-right: 10px;
  background-color: #28a745;
  color: white;
  border: none;
  padding: 40px 80px; /* 4x original: 10px 20px */
	margin: 20px;
  font-size: 64px;     /* 4x original: 16px */
  border-radius: 24px; /* 4x original: 6px */
  cursor: pointer;
  box-shadow: 0 16px 24px rgba(0, 0, 0, 0.1); /* scaled up */
  transition: background-color 0.3s ease, box-shadow 0.3s ease;
}

button[onclick*="start"]:hover {
  background-color: #218838;
  box-shadow: 0 24px 32px rgba(0, 0, 0, 0.15);
}

/* STOP button */
button[onclick*="stop"] {
  background-color: #dc3545;
  color: white;
  border: none;
  padding: 40px 80px;
	margin: 20px;
  font-size: 64px;
  border-radius: 24px;
  cursor: pointer;
  box-shadow: 0 16px 24px rgba(0, 0, 0, 0.1);
  transition: background-color 0.3s ease, box-shadow 0.3s ease;
}

button[onclick*="stop"]:hover {
  background-color: #c82333;
  box-shadow: 0 24px 32px rgba(0, 0, 0, 0.15);
}
